+import fs from 'node:fs';import crypto from 'node:crypto';
+const P=new URL('./scenario/东岸末班船-再扩展验证/',import.meta.url);const r=p=>fs.readFileSync(new URL(p,P)),h=p=>crypto.createHash('sha256').update(r(p)).digest('hex'),put=(p,v)=>fs.writeFileSync(new URL(p,P),typeof v==='string'?v:JSON.stringify(v,null,2)+'\n',{flag:'wx'});
+const t=JSON.parse(r('.writer/drafts/dr-review-template31-36-r164.json')),state=JSON.parse(r('.writer/state.json')),paths=new Map(state.units.map(u=>[u.unit,u.draft]));
+const tx=n=>r(paths.get(n)).toString();const ev=(unit,quote)=>{if(!tx(unit).includes(quote))throw Error(`quote absent in ${unit}: ${quote}`);return {unit,quote};};const ob=(n,text,quote)=>({status:'observed',text,evidence:[ev(n,quote)]});
+const data=[
+[31,[['为真正赴茶约留出工时，让女儿修裤进入正常穿衣上班。','午后两点到四点不在。'],['临时折椅客当天要用，工时与茶约冲突，不是只需拧螺丝。','横杆接头有裂'],['不接赶不出的活、收工具包以普通朋友身份出门。','工具包放回柜后。'],['折椅生意流走而14点约仍有可走的空当，门纸落地。','周岸没能留下这笔活，也没问人家后来找谁。'],['把廖从吃面/做活的对象明确说成可以去家里喝茶的人。','到廖师傅家喝茶。']]],
+[32,[['让25远约真正成为两人坐饮的时间。','先给他那只花杯倒到半杯'],['工作的手习惯、手机与邻居椅背问询仍随时挤进私人坐处。','眼睛总先找一颗没收的螺丝'],['柜门电话等回铺有本子再回，不起身给邻居现场修。','周岸按灭屏，将手机放回身边'],['13:58到近16实坐，之后各回工作；下午歇过不抹去晚市脚累。','等周岸再看时间，已经差几分四点。'],['能从叶影聊到清水面和小时候的旧书，交流不必依工件开场。','不用先把一项活摆在人中间。']]],
+[33,[['把母亲具体穿洗用感真正送到老师眼前，并问自己的旧练布。','我带了上次说的用感'],['衣服未带/只凭纸不能决定剪角；女孩怕仍认角就是自己没做好。','我总怕她一说还能认得，就是我没弄好。'],['保留母原话加旁注，特地送纸而不把未观察的抬手受力写成肯定。','母亲说：抬手未压肘'],['老师实际读纸再递回，旧练布仅捏平没新缝；不是第四次课。','老师把纸递回。'],['母亲使用经验进入学习关系，老师限定在她那一件；女儿也能为自己的练习发问。','你母亲说的是她那一件，别拿这句话替别人定布厚。']]],
+[34,[['把次日书约从远期计划推进到真实前日互告及生活准备。','明日周日，两点，原来那家旧书店门前。我中午回家吃过再去。'],['另一家房门底加条裂、拆清需时间，主人十点另有出门。','她们十点要走'],['不卸未看清的底条，不强迫老人取消原行程。','自己今天先不卸。'],['松椅有限试用后20实付收/带离，工装三洗到夜仍凉。','二十元从钱夹里取出，是一张整的。'],['父亲看过原册又主动归还，父女可各看到对方没看的细节。','先给你。我这页认住了。']]],
+[35,[['让原14点书约变为两人真实共同看书。','我们约来的。'],['店书图文比例与个人欲望不同，花名不识，买否不能由同伴决定。','后头都是小文章。'],['沈看中18薄书仍选择放回，女保留密红花兴趣。','说这本今天先不拿'],['女自付12实得纸包花册，沈20未花，同坐水再分路。','姑娘用自己的手机付了十二元。'],['朋友意见可以交换而不要求跟着换兴趣。','我想听你说。又不是听完就得换。']]],
+[36,[['将共同挑看带回各自阅读、休息和学习生活。','她想起答应沈禾拍红的'],['工作家务挤时间、图可有不同解释，折平与拉线仍两回事。','被自己拉线扯成一道小波'],['周午后真正家饭睡醒不赶料，女练少量后收针继续看自己的花。','回说今日不过来，下回需要再问。'],['照片真发回应，母三洗后再穿新条留家，六七针仍未齐。','周一，三洗后穿，靠桌还认角'],['母女谈话越过补衣成败，母亲有自己值守和听戏的下午。','我坐一下午，不是只为了回来交这两句。']]]
+];
+const keys=['goal','obstacle','choice','consequence','relationship_change'];t.chapter_functions=data.map(([unit,arr])=>Object.fromEntries([['unit',unit],...keys.map((k,i)=>[k,ob(unit,...arr[i])])]));
+const cmp=(units,judgment,differences,preserve,optional_adjustments,uncertainty,quotes)=>({units,judgment,differences,preserve,optional_adjustments,uncertainty,evidence:units.map((n,i)=>ev(n,quotes[i]))});
